/** Markers around the part of a shared file (AGENTS.md, copilot-instructions.md) that kbx owns. */
export const BLOCK_START =
  "<!-- kbx:start (generated by `kbx export`; edits inside are overwritten) -->";
export const BLOCK_END = "<!-- kbx:end -->";

const BLOCK = /<!-- kbx:start[^>]*-->[\s\S]*?<!-- kbx:end -->/;

/** Puts `block` into `existing`: replacing the marked part if present, else appending it. */
export function replaceBlock(existing: string | undefined, block: string): string {
  if (!existing?.trim()) return `${block}\n`;
  if (BLOCK.test(existing)) return existing.replace(BLOCK, block);
  return `${existing.trimEnd()}\n\n${block}\n`;
}

/** Removes the marked part, leaving hand-written content as it was. */
export function removeBlock(existing: string): string {
  const rest = existing
    .replace(BLOCK, "")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
  return rest ? `${rest}\n` : "";
}
